namespace sv_c87bf22acbfe4fb3b880a294808c852e.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per SignalR circuit (i.e. per browser tab).
/// All Interactive Server components share the same instance regardless of
/// whether they live in the layout or in page content.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#1b6ec2";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (string.Equals(_accentColor, value, StringComparison.OrdinalIgnoreCase)) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Subscribers must call InvokeAsync(StateHasChanged) to re-render.
    /// </summary>
    public event Action? OnThemeChanged;

    private void NotifyChanged() => OnThemeChanged?.Invoke();
}

// Applied by ThemeProvider via JS interop.
// Sets data-theme on <html> so CSS can respond, plus a custom property for accent color.
export function applyTheme(theme, accentColor) {
    document.documentElement.setAttribute('data-theme', theme.toLowerCase());
    document.documentElement.style.setProperty('--accent-color', accentColor);
}

@* 
    Interactive island that lives in the static MainLayout.
    It bridges ThemeService → JS so the browser always reflects the current theme.
    Because it's interactive and in the layout, its circuit survives enhanced navigation.
*@
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += OnThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/theme.js");
            await PushThemeToJs();
        }
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await PushThemeToJs();
            StateHasChanged();
        });
    }

    private async Task PushThemeToJs()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
        }
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnThemeChanged -= OnThemeChanged;
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

@* Interactive island in the header that shows the current theme and lets the user cycle it. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary theme-indicator"
        @onclick="CycleTheme"
        title="Current theme – click to change">
    @Icon @ThemeService.Theme
    <span class="accent-dot" style="background-color: @ThemeService.AccentColor;"></span>
</button>

@code {
    private string Icon => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += OnThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
    }

    private void OnThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnThemeChanged -= OnThemeChanged;
}

.theme-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.85rem;
}

.accent-dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    border: 1px solid rgba(0,0,0,0.2);
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var active = ThemeService.Theme == mode;
                <button type="button"
                        class="btn @(active ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeService.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentChanged" />
            <span class="text-muted">@ThemeService.AccentColor</span>
        </div>

        <div class="alert alert-info mb-0">
            Changes are applied instantly across the entire app.
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += OnThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#1b6ec2";
    }

    private void OnThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnThemeChanged -= OnThemeChanged;
}

