toolArgs.file_text:
@* 
    Interactive island that lives in the static MainLayout.
    It bridges ThemeService → JS so the browser always reflects the current theme.
    Because it's interactive and in the layout, its circuit survives enhanced navigation.
*@
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += OnThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/theme.js");
            await PushThemeToJs();
        }
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await PushThemeToJs();
            StateHasChanged();
        });
    }

    private async Task PushThemeToJs()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
        }
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnThemeChanged -= OnThemeChanged;
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

