/* ── Theme support ────────────────────────────────────────── */

:root {
    --accent-color: #1b6ec2;
}

/* Override Bootstrap link / button colors with the accent */
a, .btn-link {
    color: var(--accent-color);
}
.btn-primary {
    background-color: var(--accent-color);
    border-color: var(--accent-color);
}

/* Dark theme overrides (applied via data-theme on <html>) */
[data-theme="dark"] {
    background-color: #1a1a2e;
    color: #e0e0e0;
}
[data-theme="dark"] .top-row {
    background-color: #16213e;
    border-bottom-color: #0f3460;
}
[data-theme="dark"] .card {
    background-color: #16213e;
    border-color: #0f3460;
    color: #e0e0e0;
}
[data-theme="dark"] .alert-info {
    background-color: #0f3460;
    border-color: #1a1a5e;
    color: #e0e0e0;
}
[data-theme="dark"] .sidebar {
    background-image: linear-gradient(180deg, #0d1b2a 0%, #1b0a2e 70%);
}

/* System theme defers to the user's OS preference */
@media (prefers-color-scheme: dark) {
    [data-theme="system"] {
        background-color: #1a1a2e;
        color: #e0e0e0;
    }
